contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept two inputs: depositAmount to deposit into c, and cashOutAmount to attempt withdrawal.
    // The function is payable because we will forward Ether when depositing into c.
    function run(uint depositAmount, uint cashOutAmount) public payable {
        require(address(this).balance >= depositAmount);
        // initial observed balance stored in c for this test contract
        uint beforeRecorded = c.balances(address(this));
        uint beforeContractEth = address(c).balance;
        // If depositAmount meets MinDeposit, Deposit should increase recorded balance and contract balance.
        // Make the deposit call (may be zero or any value).
        c.Deposit{value: depositAmount}();

        uint afterDepositRecorded = c.balances(address(this));
        uint afterDepositContractEth = address(c).balance;

        // Now attempt CashOut of cashOutAmount. Capture whether it reverted.
        bool reverted;
        try c.CashOut(cashOutAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint finalRecorded = c.balances(address(this));
        uint finalContractEth = address(c).balance;

        // The property: if CashOut succeeded (not reverted), then the recorded balance must have decreased by exactly the
        // withdrawn amount and the contract's ether balance must have decreased by at least that amount (it will be exactly
        // that amount unless the recipient failed to receive funds, but in this contract recipient is this test contract
        // and call should succeed so contract balance decreases by the same amount). If CashOut reverted, recorded balance unchanged.
        assert(
            // Case when it reverted: balances must be unchanged from after deposit
            (reverted && finalRecorded == afterDepositRecorded)
            ||
            // Case when it succeeded: finalRecorded == afterDepositRecorded - cashOutAmount
            (!reverted && finalRecorded + cashOutAmount == afterDepositRecorded)
        );
    }

    // receive to accept Ether sent by C during CashOut
    receive() external payable {}
}

