contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take an amount to try to cash out. The contract must already have sufficient recorded balance
    // for this test to observe a successful CashOut path. We therefore first ensure the test contract
    // has recorded balance by calling Deposit with depositAmount (which may be 0..). Then we attempt CashOut.
    function run(uint depositAmount, uint cashAmount) public payable {
        // ensure we have funds available to forward the deposit
        require(address(this).balance >= depositAmount);

