        // and this contract's balance must have increased by exactly cashAmount, and contract's balance decreased by same.
        // Otherwise (reverted) we only require that recorded balance did not decrease because of a failed CashOut
        // (it must be unchanged compared to just before the CashOut attempt).
        assert(
            (!reverted) ? (
                // successful: recordedAfter + cashAmount == recordedAfterDeposit  AND thisBalAfter == beforeThisBal + (recordedAfterDeposit - recordedAfter) AND c's balance decreased accordingly
                (recordedAfterDeposit >= recordedAfter) && (recordedAfter + cashAmount == recordedAfterDeposit) &&
                (thisBalAfter == beforeThisBal + cashAmount) && (cBalAfter + cashAmount == cBalAfterDeposit)
            ) : (
                // reverted: recorded balance unchanged by the CashOut attempt
                (recordedAfter == recordedAfterDeposit) && (thisBalAfter == beforeThisBal - depositAmount + (recordedAfterDeposit - beforeRecorded))
            )
        );
    }

    // accept ether sent by C during CashOut
    receive() external payable {}
